/* NEO AI Research — progressive enhancement for /research/* and /search/.
   Loaded with `defer`. Nothing here is critical content: every page renders
   completely with JavaScript disabled, per the corpus rendering rule.

   Deliberately standalone. The landing bundle is NOT loaded on a research page:
   app-runtime.min.js dereferences #langSel without a guard and throws when that
   element is absent, which would kill every later script on the page. */
(function () {
  'use strict';

  /* ---------------- disclosure navigation (below 1080px) ---------------- */
  var burger = document.querySelector('.r-burger');
  var menu = document.getElementById('rMenu');
  if (burger && menu) {
    var setOpen = function (open) {
      burger.setAttribute('aria-expanded', open ? 'true' : 'false');
      menu.classList.toggle('open', open);
      burger.setAttribute('aria-label', open ? 'Close navigation' : 'Open navigation');
    };
    burger.addEventListener('click', function () {
      setOpen(burger.getAttribute('aria-expanded') !== 'true');
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === 'Escape' && burger.getAttribute('aria-expanded') === 'true') {
        setOpen(false); burger.focus();
      }
    });
    document.addEventListener('click', function (e) {
      if (burger.getAttribute('aria-expanded') !== 'true') return;
      if (!menu.contains(e.target) && !burger.contains(e.target)) setOpen(false);
    });
  }

  /* ---------------- table of contents: current section ------------------ */
  var toc = document.querySelector('.r-toc');
  if (toc && 'IntersectionObserver' in window) {
    var links = {};
    Array.prototype.forEach.call(toc.querySelectorAll('a[href^="#"]'), function (a) {
      links[a.getAttribute('href').slice(1)] = a;
    });
    var heads = document.querySelectorAll('.r-body h2[id], .r-body h3[id]');
    if (heads.length) {
      var seen = [];
      var io = new IntersectionObserver(function (entries) {
        entries.forEach(function (en) {
          var id = en.target.id;
          var i = seen.indexOf(id);
          if (en.isIntersecting) { if (i < 0) seen.push(id); }
          else if (i >= 0) { seen.splice(i, 1); }
        });
        for (var k in links) links[k].removeAttribute('aria-current');
        if (seen.length && links[seen[0]]) {
          links[seen[0]].setAttribute('aria-current', 'true');
        }
      }, { rootMargin: '-100px 0px -70% 0px' });
      Array.prototype.forEach.call(heads, function (h) { io.observe(h); });
    }
  }

  /* ---------------- search ---------------------------------------------- */
  var input = document.getElementById('q');
  var out = document.getElementById('results');
  if (!input || !out) return;

  var DOCS = null, loading = false, pending = null;

  function load(cb) {
    if (DOCS) { cb(); return; }
    if (loading) { pending = cb; return; }
    loading = true;
    var x = new XMLHttpRequest();
    x.open('GET', '/assets/search-index.json', true);
    x.onreadystatechange = function () {
      if (x.readyState !== 4) return;
      loading = false;
      if (x.status >= 200 && x.status < 300) {
        try { DOCS = JSON.parse(x.responseText).d || []; }
        catch (e) { DOCS = []; }
      } else { DOCS = []; }
      cb(); if (pending) { var p = pending; pending = null; p(); }
    };
    x.onerror = function () {
      loading = false; DOCS = [];
      out.innerHTML = '<p class="r-warn">The search index could not be loaded. ' +
        'Every page it covers is reachable from ' +
        '<a href="/research/">the research index</a>.</p>';
    };
    x.send();
  }

  function esc(s) {
    return String(s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }

  function mark(text, terms) {
    var s = esc(text);
    terms.forEach(function (t) {
      if (t.length < 2) return;
      s = s.replace(new RegExp('(' + t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + ')', 'ig'),
        '<mark>$1</mark>');
    });
    return s;
  }

  function score(doc, terms) {
    var t = doc.t.toLowerCase(), s = (doc.s || '').toLowerCase();
    var k = (doc.k || '').toLowerCase(), n = 0;
    for (var i = 0; i < terms.length; i++) {
      var q = terms[i];
      if (t === q) n += 100;
      else if (t.indexOf(q) === 0) n += 40;
      else if (t.indexOf(q) >= 0) n += 22;
      if (k.indexOf(q) >= 0) n += 8;
      if (s.indexOf(q) >= 0) n += 4;
    }
    return n;
  }

  function run() {
    var raw = input.value.trim();
    if (raw.length < 2) {
      out.innerHTML = ''; return;
    }
    load(function () {
      var terms = raw.toLowerCase().split(/\s+/).filter(Boolean);
      var hits = [];
      for (var i = 0; i < DOCS.length; i++) {
        var n = score(DOCS[i], terms);
        if (n > 0) hits.push([n, DOCS[i]]);
      }
      hits.sort(function (a, b) { return b[0] - a[0]; });
      hits = hits.slice(0, 30);
      if (!hits.length) {
        out.innerHTML = '<p class="r-empty">Nothing in the corpus matches ' +
          esc(raw) + '. The corpus is small: six identifiers are approved and ' +
          'one document is published. ' +
          '<a href="/research/roadmap/">The roadmap</a> names what is registered ' +
          'and not published.</p>';
        return;
      }
      var h = '';
      for (var j = 0; j < hits.length; j++) {
        var d = hits[j][1];
        h += '<a class="r-hit" href="' + esc(d.u) + '">' +
          '<span class="r-hit-k">' + esc(d.k) + '</span>' +
          '<span class="r-hit-t">' + mark(d.t, terms) + '</span>' +
          (d.s ? '<span class="r-hit-s">' + mark(d.s.slice(0, 180), terms) +
            '</span>' : '') + '</a>';
      }
      out.innerHTML = h;
    });
  }

  var timer = null;
  input.addEventListener('input', function () {
    clearTimeout(timer); timer = setTimeout(run, 130);
  });

  /* deep link: /search/?q=… . The route is noindex, follow, and the parameter
     is disallowed in robots.txt, so this creates no indexable surface. */
  var m = /[?&]q=([^&]+)/.exec(location.search);
  if (m) {
    try { input.value = decodeURIComponent(m[1].replace(/\+/g, ' ')); } catch (e) { }
    run();
  }
  input.focus({ preventScroll: true });
})();
